local addonName, ns = ...
local API = ns.API

-- ---------------------------------------------------------------------------
-- WoWSims rotation evaluator.
--
-- SimData_<game>.lua (generated by tools/wowsims_convert.py) holds WoWSims
-- priority lists converted to compact tables:
--   item  = { id = spellID, c = condition, ch = true (channel) }
--         | { hold = true, c = condition }   -- "wait while X": stop suggesting
--   value = constant | { k = "kind", ...fields, v = { children } }
-- This file evaluates those conditions against the live game each tick and
-- returns the first three castable spells in priority order.
--
-- Every value kind here must also be listed in SUPPORTED in the converter;
-- tools/test_sim.py checks the two stay in sync.
-- ---------------------------------------------------------------------------

ns.Sim = ns.Sim or {}
local Sim = ns.Sim
local V = {}
Sim.HANDLERS = V

local GetTime = GetTime
local huge = 999

local function readable(v)
	if issecretvalue and issecretvalue(v) then
		return false
	end
	return v ~= nil
end

local function num(v, default)
	if v == nil or not readable(v) then
		return default or 0
	end
	return tonumber(v) or default or 0
end

local function passOk(ok, ...)
	if not ok then
		return nil
	end
	return ...
end

-- pcall wrapper: returns the function's results, or nil if it's missing or errors.
local function call(fn, ...)
	if type(fn) ~= "function" then
		return nil
	end
	return passOk(pcall(fn, ...))
end

-- ------------------------------------------------------------------ state
local pass = {}
local combatStart = 0
local ttd = { guid = nil, t0 = 0, h0 = 0 }

local function now()
	return pass.now or GetTime()
end

local function inCombat()
	return call(UnitAffectingCombat, "player") and true or false
end

local function healthFrac(unit)
	local cur = num(call(UnitHealth, unit), 0)
	local max = num(call(UnitHealthMax, unit), 0)
	if max <= 0 then
		return 1
	end
	return cur / max
end

-- Fight length estimate from the target's health drop (time to die).
local function remainingTime()
	if pass.remaining then
		return pass.remaining
	end
	local guid = call(UnitGUID, "target")
	local h = healthFrac("target")
	local t = now()
	local est = 300
	if guid and readable(guid) then
		if ttd.guid ~= guid or h > ttd.h0 then
			ttd.guid, ttd.t0, ttd.h0 = guid, t, h
		else
			local dt = t - ttd.t0
			local dh = ttd.h0 - h
			if dt > 2 and dh > 0 then
				est = h / (dh / dt)
			end
		end
	end
	if est > 900 then
		est = 900
	end
	pass.remaining = est
	return est
end

local function currentTime()
	if not inCombat() or combatStart <= 0 then
		return 0
	end
	return now() - combatStart
end

-- ------------------------------------------------------------------ spells
local function resolve(id)
	if not id then
		return nil
	end
	pass.resolved = pass.resolved or {}
	local r = pass.resolved[id]
	if r == nil then
		r = Sim.LiveSpell(id) or false
		pass.resolved[id] = r
	end
	return r or nil
end

-- The spell a rotation line means right now, as the action bar shows it.
-- - A base spell (Shadow Bolt) becomes its active override (Touch of Chaos
--   during Metamorphosis), so the HUD icon matches the button you press.
-- - An override spell (Touch of Chaos) only exists while its override is
--   active; otherwise nil.
function Sim.LiveSpell(id)
	if not API.Resolve then
		return nil
	end
	local baseOf = API.BaseSpell or function() return nil end
	local overrideOf = API.CurrentOverride or function(x) return x end
	local base = baseOf(id)
	if base then
		local known = API.Resolve(base)
		if known then
			local live = overrideOf(baseOf(known) or known)
			if live == id then
				return id
			end
			return nil
		end
		return API.Resolve(id)
	end
	local known = API.Resolve(id)
	if not known then
		return nil
	end
	return overrideOf(baseOf(known) or known)
end

local function gcdRemain()
	if pass.gcd then
		return pass.gcd
	end
	local start, duration = 0, 0
	if C_Spell and C_Spell.GetSpellCooldown then
		local info = call(C_Spell.GetSpellCooldown, 61304)
		if type(info) == "table" then
			start, duration = num(info.startTime), num(info.duration)
		end
	elseif GetSpellCooldown then
		local s, d = call(GetSpellCooldown, 61304)
		start, duration = num(s), num(d)
	end
	local left = (duration > 0) and math.max(0, start + duration - now()) or 0
	pass.gcd = left
	return left
end

-- Cooldown remaining, ignoring the global cooldown.
local function cooldownRemain(id)
	local rid = resolve(id)
	if not rid then
		return huge
	end
	local remain, duration = API.Cooldown(rid)
	remain, duration = num(remain), num(duration)
	if duration > 0 and duration <= 1.55 then
		return 0
	end
	local g = gcdRemain()
	if remain <= g + 0.05 then
		return 0
	end
	return remain
end

-- The game's own "can I press this" answer. True/false, or nil if unknown.
-- Catches spells that need a proc or stacks (Dark Transformation needs 5
-- Shadow Infusion), forms, targets and resources.
local function usableNow(rid)
	local usable, noPower
	if C_Spell and C_Spell.IsSpellUsable then
		usable, noPower = call(C_Spell.IsSpellUsable, rid)
	end
	if usable == nil and IsUsableSpell then
		usable, noPower = call(IsUsableSpell, rid)
	end
	if not readable(usable) then
		return nil
	end
	if usable == true and noPower ~= true then
		return true
	elseif usable == false or noPower == true then
		return false
	end
	return nil
end

local function canCast(id)
	local rid = resolve(id)
	if not rid then
		return false
	end
	if cooldownRemain(rid) > 0.2 then
		return false
	end
	-- Forever marks every spell unusable during the GCD, so it keeps the
	-- original lenient check; every other client trusts the game's answer.
	if ns.GAME ~= "forever" then
		local u = usableNow(rid)
		if u ~= nil then
			return u
		end
	end
	return API.Ready(rid, nil, true) and true or false
end

local function spellName(id)
	if API.SpellName then
		return API.SpellName(id)
	end
	local info = C_Spell and C_Spell.GetSpellInfo and call(C_Spell.GetSpellInfo, id)
	return type(info) == "table" and info.name or nil
end

local function isPlayerSpell(id)
	if call(IsPlayerSpell, id) then
		return true
	end
	if call(IsSpellKnown, id) then
		return true
	end
	return false
end

-- ------------------------------------------------------------------ auras
local function scanAuras(unit, filter)
	local key = unit .. "|" .. filter
	pass.auras = pass.auras or {}
	local list = pass.auras[key]
	if list then
		return list
	end
	list = {}
	if C_UnitAuras and C_UnitAuras.GetAuraDataByIndex then
		for i = 1, 40 do
			local aura = call(C_UnitAuras.GetAuraDataByIndex, unit, i, filter)
			if type(aura) ~= "table" then
				break
			end
			list[#list + 1] = {
				id = readable(aura.spellId) and aura.spellId or nil,
				name = readable(aura.name) and aura.name or nil,
				count = num(aura.applications, 0),
				expires = num(aura.expirationTime, 0),
				duration = num(aura.duration, 0),
			}
		end
	elseif UnitAura then
		for i = 1, 40 do
			local name, _, count, _, duration, expires, _, _, _, spellId = call(UnitAura, unit, i, filter)
			if not name then
				break
			end
			list[#list + 1] = { id = spellId, name = name, count = num(count), expires = num(expires), duration = num(duration) }
		end
	end
	pass.auras[key] = list
	return list
end

-- Find an aura by spell ID (or, failing that, by spell name).
local function findAura(id, unit, mine)
	unit = unit or "player"
	local name = spellName(id)
	local filters
	if mine then
		filters = { "HARMFUL|PLAYER", "HELPFUL|PLAYER" }
	else
		filters = { "HELPFUL", "HARMFUL" }
	end
	for _, filter in ipairs(filters) do
		local list = scanAuras(unit, filter)
		for _, a in ipairs(list) do
			if a.id == id then
				return a
			end
		end
		if name then
			for _, a in ipairs(list) do
				if a.name == name then
					return a
				end
			end
		end
	end
	return nil
end

local function auraRemain(a)
	if not a then
		return 0
	end
	if a.expires <= 0 then
		return huge -- permanent aura
	end
	return math.max(0, a.expires - now())
end

-- ------------------------------------------------------------------ runes
-- WoW rune slots: 1-2 Blood, 3-4 Unholy, 5-6 Frost. GetRuneType: 1 Blood, 2 Unholy, 3 Frost, 4 Death.
local RUNE_SLOTS = { blood = { 1, 2 }, unholy = { 3, 4 }, frost = { 5, 6 } }

local function rune(slot)
	pass.runes = pass.runes or {}
	local r = pass.runes[slot]
	if r then
		return r
	end
	local start, duration, ready = call(GetRuneCooldown, slot)
	local kind = num(call(GetRuneType, slot), 0)
	start, duration = num(start), num(duration)
	local remain = 0
	if not ready and duration > 0 then
		remain = math.max(0, start + duration - now())
	end
	r = { ready = ready and true or remain <= 0, remain = remain, death = kind == 4, duration = duration }
	pass.runes[slot] = r
	return r
end

local function runeSlotsFor(kind)
	if kind == "death" then
		local out = {}
		for s = 1, 6 do
			if rune(s).death then
				out[#out + 1] = s
			end
		end
		return out
	end
	return RUNE_SLOTS[kind] or {}
end

-- ------------------------------------------------------------------ power
local POWER = { mana = 0, rage = 1, focus = 2, energy = 3, combo = 4, runic = 6, shards = 7, eclipse = 8,
	holy = 9, chi = 12, orbs = 13, embers = 14, fury = 15 }

local function power(kind)
	return num(call(UnitPower, "player", POWER[kind]), 0)
end

local function powerMax(kind)
	return num(call(UnitPowerMax, "player", POWER[kind]), 0)
end

local function regen()
	local inactive, active = call(GetPowerRegen)
	active = num(active, 0)
	if active <= 0 then
		active = num(inactive, 0)
	end
	return active
end

local function haste()
	return num(call(UnitSpellHaste, "player"), 0) / 100
end

local function genericResource()
	local token = ns.ClassToken and ns.ClassToken()
	if token == "PALADIN" then
		return power("holy")
	elseif token == "PRIEST" then
		return power("orbs")
	elseif token == "MONK" then
		return power("chi")
	elseif token == "WARLOCK" then
		local spec = Sim.Spec()
		if spec == 2 then
			return power("fury")
		elseif spec == 3 then
			return num(call(UnitPower, "player", POWER.embers, true), 0) / 10
		end
		return power("shards")
	end
	return 0
end

-- ------------------------------------------------------------------ spec
-- Current specialization index (1-4), or 0. Newer clients moved the old
-- globals into C_SpecializationInfo, so try that first.
function Sim.Spec()
	local api = type(C_SpecializationInfo) == "table" and C_SpecializationInfo or nil
	if api and api.GetSpecialization then
		local s = num(call(api.GetSpecialization), 0)
		if s > 0 then
			return s
		end
	end
	local s = num(call(GetSpecialization), 0)
	if s > 0 then
		return s
	end
	return 0
end

-- Localized spec name for an index, or nil.
function Sim.SpecName(spec)
	local api = type(C_SpecializationInfo) == "table" and C_SpecializationInfo or nil
	local fns = { api and api.GetSpecializationInfo or false, GetSpecializationInfo or false }
	for i = 1, 2 do
		local fn = fns[i]
		if type(fn) == "function" then
			local _, name = call(fn, spec)
			if type(name) == "string" and name ~= "" then
				return name
			end
		end
	end
	return nil
end

-- Why there's no spec to work with: "client" (this client has no WoWSims
-- rotations / no specs) or "spec" (MoP client, but no spec chosen or readable).
function Sim.NoSpecReason()
	return "spec"
end

-- True when rotations can be stored/picked right now (MoP needs a spec).
function Sim.Ready()
	local token = ns.ClassToken and ns.ClassToken()
	if not token then
		return false
	end
	return not Sim.UsesSpecs() or Sim.Spec() > 0
end

-- ------------------------------------------------------------------ evaluate
local function ev(node)
	if type(node) ~= "table" then
		return node
	end
	local fn = V[node.k]
	if not fn then
		return false
	end
	return fn(node)
end
Sim.Eval = ev

local function truthy(v)
	if v == nil or v == false then
		return false
	end
	if type(v) == "number" then
		return v ~= 0
	end
	return true
end
Sim.Truthy = truthy

local function asNum(v)
	if v == true then
		return 1
	elseif v == false or v == nil then
		return 0
	end
	return tonumber(v) or 0
end

V["and"] = function(n)
	for _, c in ipairs(n.v) do
		if not truthy(ev(c)) then
			return false
		end
	end
	return true
end
V["or"] = function(n)
	for _, c in ipairs(n.v) do
		if truthy(ev(c)) then
			return true
		end
	end
	return false
end
V["not"] = function(n)
	return not truthy(ev(n.v[1]))
end
V.cmp = function(n)
	local a, b = ev(n.v[1]), ev(n.v[2])
	if type(a) == "boolean" or type(b) == "boolean" then
		a, b = truthy(a), truthy(b)
		if n.op == "==" then
			return a == b
		elseif n.op == "~=" then
			return a ~= b
		end
		a, b = a and 1 or 0, b and 1 or 0
	end
	a, b = asNum(a), asNum(b)
	local op = n.op
	if op == "==" then
		return math.abs(a - b) < 1e-6
	elseif op == "~=" then
		return math.abs(a - b) >= 1e-6
	elseif op == "<" then
		return a < b
	elseif op == "<=" then
		return a <= b
	elseif op == ">" then
		return a > b
	elseif op == ">=" then
		return a >= b
	end
	return false
end
V.math = function(n)
	local a, b = asNum(ev(n.v[1])), asNum(ev(n.v[2]))
	local op = n.op
	if op == "+" then
		return a + b
	elseif op == "-" then
		return a - b
	elseif op == "*" then
		return a * b
	elseif op == "/" then
		return b ~= 0 and a / b or 0
	end
	return 0
end
V.max = function(n)
	local best
	for _, c in ipairs(n.v) do
		local x = asNum(ev(c))
		if not best or x > best then
			best = x
		end
	end
	return best or 0
end
V.min = function(n)
	local best
	for _, c in ipairs(n.v) do
		local x = asNum(ev(c))
		if not best or x < best then
			best = x
		end
	end
	return best or 0
end

-- encounter
V.currentTime = function()
	return currentTime()
end
V.remainingTime = function()
	return remainingTime()
end
V.currentTimePercent = function()
	local c, r = currentTime(), remainingTime()
	return (c + r) > 0 and c / (c + r) or 0
end
V.remainingTimePercent = function()
	local c, r = currentTime(), remainingTime()
	return (c + r) > 0 and r / (c + r) or 1
end
V.isExecutePhase = function(n)
	return healthFrac("target") <= (n.pct or 0.2)
end
V.numberTargets = function()
	local count = num(API.EnemyCount and API.EnemyCount(), 0)
	if count < 1 then
		count = 1
	end
	return count
end
V.bossCurrentTarget = function()
	return call(UnitIsUnit, "targettarget", "player") and true or false
end

-- health / mana
V.currentHealth = function(n)
	return num(call(UnitHealth, n.unit or "player"), 0)
end
V.currentHealthPercent = function(n)
	return healthFrac(n.unit or "player")
end
V.maxHealth = function()
	return num(call(UnitHealthMax, "player"), 0)
end
V.currentMana = function()
	return power("mana")
end
V.currentManaPercent = function()
	local m = powerMax("mana")
	return m > 0 and power("mana") / m or 0
end

-- resources
V.currentRage = function()
	return power("rage")
end
V.maxRage = function()
	return powerMax("rage")
end
V.currentEnergy = function()
	return power("energy")
end
V.maxEnergy = function()
	return powerMax("energy")
end
V.currentFocus = function()
	return power("focus")
end
V.maxFocus = function()
	return powerMax("focus")
end
V.energyRegenPerSecond = function()
	return regen()
end
V.focusRegenPerSecond = function()
	return regen()
end
V.energyTimeToTarget = function(n)
	local need = asNum(ev(n.target)) - power("energy")
	local r = regen()
	if need <= 0 then
		return 0
	end
	return r > 0 and need / r or huge
end
V.focusTimeToTarget = function(n)
	local need = asNum(ev(n.target)) - power("focus")
	local r = regen()
	if need <= 0 then
		return 0
	end
	return r > 0 and need / r or huge
end
V.currentComboPoints = function()
	local cp = call(GetComboPoints, "player", "target")
	if cp == nil then
		return power("combo")
	end
	return num(cp, 0)
end
V.maxComboPoints = function()
	return 5
end
V.currentRunicPower = function()
	return power("runic")
end
V.maxRunicPower = function()
	return powerMax("runic")
end
V.currentGenericResource = function()
	return genericResource()
end
V.monkCurrentChi = function()
	return power("chi")
end
V.monkMaxChi = function()
	return powerMax("chi")
end
V.brewmasterMonkCurrentStaggerPercent = function()
	local s = num(call(UnitStagger, "player"), 0)
	local m = num(call(UnitHealthMax, "player"), 0)
	return m > 0 and s / m or 0
end
V.currentSolarEnergy = function()
	return math.max(0, power("eclipse"))
end
V.currentLunarEnergy = function()
	return math.max(0, -power("eclipse"))
end
V.druidCurrentEclipsePhase = function(n)
	local solar = findAura(48517, "player")
	local lunar = findAura(48518, "player")
	if n.phase == "solar" then
		return solar ~= nil
	elseif n.phase == "lunar" then
		return lunar ~= nil
	end
	return solar == nil and lunar == nil
end

-- runes
V.currentRuneCount = function(n)
	local count = 0
	for _, s in ipairs(runeSlotsFor(n.rune)) do
		if rune(s).ready then
			count = count + 1
		end
	end
	return count
end
V.currentNonDeathRuneCount = function(n)
	local count = 0
	for _, s in ipairs(RUNE_SLOTS[n.rune] or {}) do
		local r = rune(s)
		if r.ready and not r.death then
			count = count + 1
		end
	end
	return count
end
V.currentRuneDeath = function(n)
	return rune(n.slot or 1).death
end
V.currentRuneActive = function(n)
	return rune(n.slot or 1).ready
end
V.runeCooldown = function(n)
	local best
	for _, s in ipairs(runeSlotsFor(n.rune)) do
		local r = rune(s).remain
		if not best or r < best then
			best = r
		end
	end
	return best or 0
end
V.nextRuneCooldown = function(n)
	local best
	for _, s in ipairs(runeSlotsFor(n.rune)) do
		local r = rune(s)
		if not r.ready and (not best or r.remain < best) then
			best = r.remain
		end
	end
	return best or 0
end
V.runeSlotCooldown = function(n)
	return rune(n.slot or 1).remain
end
V.fullRuneCooldown = function()
	for s = 1, 6 do
		local d = rune(s).duration
		if d > 0 then
			return d
		end
	end
	return 10 / (1 + haste())
end

-- gcd / casting / movement
V.gcdIsReady = function()
	return gcdRemain() <= 0.05
end
V.gcdTimeToReady = function()
	return gcdRemain()
end
V.remainingCastTime = function()
	local _, _, _, _, endMs = call(UnitCastingInfo, "player")
	if not endMs then
		_, _, _, _, endMs = call(UnitChannelInfo, "player")
	end
	endMs = num(endMs, 0)
	return endMs > 0 and math.max(0, endMs / 1000 - now()) or 0
end
V.unitIsMoving = function(n)
	return num(call(GetUnitSpeed, n.unit or "player"), 0) > 0
end
-- Tuning only: "stance" is the active stance-bar slot (0 = none, e.g. no
-- seal); "stance(31801)" is true while that seal/presence/stance is active.
V.playerStance = function(n)
	local st = Sim.StanceSlots()
	if n.id then
		local rid = resolve(n.id) or n.id
		return st.active ~= nil and (st.active == n.id or st.active == rid)
	end
	return st.index
end

-- spells
V.spellIsKnown = function(n)
	return resolve(n.id) ~= nil
end
V.spellCanCast = function(n)
	return canCast(n.id)
end
V.spellIsReady = function(n)
	return resolve(n.id) ~= nil and cooldownRemain(n.id) <= 0.05
end
V.spellTimeToReady = function(n)
	return cooldownRemain(n.id)
end
V.spellCastTime = function(n)
	local rid = resolve(n.id) or n.id
	local info = C_Spell and C_Spell.GetSpellInfo and call(C_Spell.GetSpellInfo, rid)
	if type(info) == "table" then
		return num(info.castTime, 0) / 1000
	end
	local _, _, _, castMs = call(GetSpellInfo, rid)
	return num(castMs, 0) / 1000
end
local function castingId(fn, idx)
	local res = { call(fn, "player") }
	return res[idx], res[1]
end
V.spellIsChanneling = function(n)
	local sid, name = castingId(UnitChannelInfo, 8)
	if not name then
		return false
	end
	return sid == n.id or sid == resolve(n.id) or name == spellName(n.id)
end
V.spellIsCasting = function(n)
	local sid, name = castingId(UnitCastingInfo, 9)
	if not name then
		return false
	end
	return sid == n.id or sid == resolve(n.id) or name == spellName(n.id)
end
V.spellCurrentCost = function(n)
	local rid = resolve(n.id) or n.id
	local costs = (C_Spell and C_Spell.GetSpellPowerCost and call(C_Spell.GetSpellPowerCost, rid)) or call(GetSpellPowerCost, rid)
	if type(costs) == "table" and type(costs[1]) == "table" then
		return num(costs[1].cost, 0)
	end
	return 0
end
local function charges(id)
	local rid = resolve(id) or id
	if C_Spell and C_Spell.GetSpellCharges then
		local info = call(C_Spell.GetSpellCharges, rid)
		if type(info) == "table" then
			return num(info.currentCharges), num(info.maxCharges), num(info.cooldownStartTime), num(info.cooldownDuration)
		end
	end
	local c, m, s, d = call(GetSpellCharges, rid)
	return num(c), num(m), num(s), num(d)
end
V.spellNumCharges = function(n)
	local c, m = charges(n.id)
	if m <= 0 then
		return canCast(n.id) and 1 or 0
	end
	return c
end
V.spellTimeToCharge = function(n)
	local c, m, s, d = charges(n.id)
	if m <= 0 or c >= m or d <= 0 then
		return 0
	end
	return math.max(0, s + d - now())
end
V.spellGcdHastedDuration = function()
	return math.max(1, 1.5 / (1 + haste()))
end
V.spellFullCooldown = function(n)
	local rid = resolve(n.id) or n.id
	return num(call(GetSpellBaseCooldown, rid), 0) / 1000
end

-- auras
V.auraIsKnown = function(n)
	return isPlayerSpell(n.id) or resolve(n.id) ~= nil
end
V.auraIsActive = function(n)
	return findAura(n.id, n.unit) ~= nil
end
V.auraIsInactive = function(n)
	return findAura(n.id, n.unit) == nil
end
V.auraRemainingTime = function(n)
	return auraRemain(findAura(n.id, n.unit))
end
V.auraNumStacks = function(n)
	local a = findAura(n.id, n.unit)
	return a and a.count or 0
end
V.auraShouldRefresh = function(n)
	local mine = n.unit == "target"
	local a = findAura(n.id, n.unit, mine)
	if not a then
		return true
	end
	return auraRemain(a) <= asNum(ev(n.overlap))
end

-- dots (player-cast auras on the target)
V.dotIsActive = function(n)
	return findAura(n.id, n.unit or "target", true) ~= nil
end
V.dotIsActiveOnAllTargets = function(n)
	return findAura(n.id, "target", true) ~= nil
end
V.dotRemainingTime = function(n)
	return auraRemain(findAura(n.id, n.unit or "target", true))
end
V.dotLowestRemainingTime = function(n)
	return auraRemain(findAura(n.id, "target", true))
end
V.dotTickFrequency = function()
	return 3 / (1 + haste())
end
V.totemRemainingTime = function(n)
	local have, _, start, duration = call(GetTotemInfo, n.slot or 1)
	if not have then
		return 0
	end
	return math.max(0, num(start) + num(duration) - now())
end

-- ------------------------------------------------------------------ rotation pick
-- Does this client have specializations that pick the rotation? (MoP yes;
-- Era/TBC/Forever no: their imported rotations are kept per class, spec 0.)
function Sim.UsesSpecs()
	return ns.GAME == "mists"
end

-- WoWSims rotations for the current class/spec, plus any imported in game
-- (SimImport.lua). Returns list (or nil), class token, spec index.
function Sim.Rotations()
	local token = ns.ClassToken and ns.ClassToken()
	local spec = Sim.Spec()
	if not Sim.UsesSpecs() then
		spec = 0
	end
	if not token or (spec == 0 and Sim.UsesSpecs()) then
		return nil, token, spec
	end
	local data = ns.SimData
	local base = data and data.specs and data.specs[token] and data.specs[token][spec]
	local imported = Sim.Imported and Sim.Imported(token, spec) or {}
	local workshop = Sim.Workshop and Sim.Workshop(token, spec) or {}
	if #imported == 0 and #workshop == 0 then
		return base, token, spec
	end
	local list = {}
	for _, rot in ipairs(base or {}) do
		list[#list + 1] = rot
	end
	for _, rot in ipairs(workshop) do
		list[#list + 1] = rot
	end
	for _, rot in ipairs(imported) do
		list[#list + 1] = rot
	end
	return list, token, spec
end

function Sim.Current()
	local list, token, spec = Sim.Rotations()
	if not list or #list == 0 then
		return nil
	end
	local pick = ns.db and ns.db.simPick and ns.db.simPick[token .. ":" .. spec]
	if pick then
		for _, rot in ipairs(list) do
			if rot.file == pick then
				return rot
			end
		end
	end
	return list[1]
end

function Sim.Active()
	return Sim.Current() ~= nil
end

-- /rcr apl: switch to the next WoWSims rotation for this spec.
function Sim.Cycle()
	local list, token, spec = Sim.Rotations()
	if not list or #list == 0 then
		return nil
	end
	local cur = Sim.Current() or list[1]
	local idx = 1
	for i, rot in ipairs(list) do
		if rot == cur then
			idx = i
		end
	end
	local nextRot = list[(idx % #list) + 1]
	ns.db.simPick = ns.db.simPick or {}
	ns.db.simPick[token .. ":" .. spec] = nextRot.file
	return nextRot, #list
end

-- ------------------------------------------------------------------ never suggest
-- Spells WoWSims uses for simulation value but a player saves for the right
-- moment: personal defensives and raid-wide cooldowns. Applied on top of every
-- rotation (bundled or imported), so WoWSims updates never bring them back.
-- Players can add or remove spells per character (HUD right-click, /rcr block).
Sim.DEFAULT_BLOCK = {
	[48707] = "Anti-Magic Shell",
	[48792] = "Icebound Fortitude",
	[51052] = "Anti-Magic Zone",
	[42650] = "Army of the Dead",
	[61999] = "Raise Ally",
	[2825] = "Bloodlust",
	[32182] = "Heroism",
	[80353] = "Time Warp",
	[90355] = "Ancient Hysteria",
	[120668] = "Stormlash Totem",
	[114207] = "Skull Banner",
	[20484] = "Rebirth",
}

-- Spec blocks from the tuning file (set per queue build; see Sim.BuildQueue).
local tuningBlock = {}

local function blockState(id)
	if not id then
		return nil
	end
	local user = ns.db and ns.db.simBlock
	if user and user[id] ~= nil then
		return user[id]
	end
	if Sim.DEFAULT_BLOCK[id] or tuningBlock[id] then
		return true
	end
	return nil
end

-- Blocked by ID (as written in the rotation or as resolved) or by name.
function Sim.IsBlocked(id, rid)
	local state = blockState(id)
	if state == nil and rid and rid ~= id then
		state = blockState(rid)
	end
	if state ~= nil then
		return state
	end
	local names = ns.db and ns.db.simBlockNames
	local name = spellName(rid or id)
	if names and name then
		for bid, bname in pairs(names) do
			if bname == name then
				local s = blockState(bid)
				if s ~= nil then
					return s
				end
			end
		end
	end
	return false
end

function Sim.SetBlocked(id, blocked)
	ns.db.simBlock = ns.db.simBlock or {}
	ns.db.simBlockNames = ns.db.simBlockNames or {}
	ns.db.simBlock[id] = blocked and true or false
	ns.db.simBlockNames[id] = spellName(id) or Sim.DEFAULT_BLOCK[id]
	if ns.InvalidateTick then
		ns.InvalidateTick()
	end
end

-- HUD right-click: stop suggesting this spell.
function Sim.ToggleBlock(id)
	local now = not Sim.IsBlocked(id)
	Sim.SetBlocked(id, now)
	if ns.Print then
		local name = spellName(id) or tostring(id)
		ns.Print(ns.T(now and "SIM_BLOCKED" or "SIM_UNBLOCKED"):format(name))
	end
	return now
end

-- Everything currently blocked: { {id=, name=, default=bool}, ... } sorted by name.
function Sim.BlockedList()
	local out, seen = {}, {}
	local function add(id)
		if not seen[id] and blockState(id) then
			seen[id] = true
			out[#out + 1] = { id = id, name = (ns.db.simBlockNames and ns.db.simBlockNames[id]) or spellName(id) or Sim.DEFAULT_BLOCK[id] or tostring(id),
				default = Sim.DEFAULT_BLOCK[id] ~= nil }
		end
	end
	for id in pairs(Sim.DEFAULT_BLOCK) do
		add(id)
	end
	for id in pairs(ns.db and ns.db.simBlock or {}) do
		add(id)
	end
	table.sort(out, function(a, b)
		return tostring(a.name) < tostring(b.name)
	end)
	return out
end

function Sim.ResetBlocks()
	ns.db.simBlock = nil
	ns.db.simBlockNames = nil
	if ns.InvalidateTick then
		ns.InvalidateTick()
	end
end

-- Resolve "/rcr block <name or id>" text to a spell ID.
function Sim.FindSpell(text)
	text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
	local id = tonumber(text)
	if id then
		return id
	end
	if text == "" then
		return nil
	end
	for bid, bname in pairs(ns.db and ns.db.simBlockNames or {}) do
		if type(bname) == "string" and bname:lower() == text:lower() then
			return bid
		end
	end
	for bid, bname in pairs(Sim.DEFAULT_BLOCK) do
		if bname:lower() == text:lower() then
			return bid
		end
	end
	local info = C_Spell and C_Spell.GetSpellInfo and call(C_Spell.GetSpellInfo, text)
	if type(info) == "table" and info.spellID then
		return info.spellID
	end
	local _, _, _, _, _, _, sid = call(GetSpellInfo, text)
	return sid
end

-- ------------------------------------------------------------------ tuning
-- Per-spec fixes from rotations/tuning/*.json, compiled into
-- ns.SimData.tuning by the converter. Applied to every rotation for the spec,
-- bundled or imported: require (extra condition), move, add, block.
local tunedCache = setmetatable({}, { __mode = "k" })

function Sim.TuningFor(rot, token, spec)
	local all = ns.SimData and ns.SimData.tuning
	if not all then
		return nil
	end
	local merged
	local keys = { "*", (token or "?") .. ":" .. tostring(spec or 0), rot and rot.file and ("file:" .. rot.file) or nil }
	for i = 1, 3 do
		local rules = keys[i] and all[keys[i]]
		if rules then
			merged = merged or { block = {}, require = {}, move = {}, add = {} }
			for kind, list in pairs(rules) do
				if merged[kind] then
					for _, r in ipairs(list) do
						merged[kind][#merged[kind] + 1] = r
					end
				end
			end
		end
	end
	return merged
end

local function indexOf(list, id)
	for i, item in ipairs(list) do
		if item.id == id then
			return i
		end
	end
	return nil
end

-- The rotation's list with the tuning applied (cached per rotation).
function Sim.ListFor(rot, token, spec)
	local rules = Sim.TuningFor(rot, token, spec)
	if not rules then
		return rot.list, nil
	end
	local cached = tunedCache[rot]
	if cached and cached.key == (token or "?") .. ":" .. tostring(spec) then
		return cached.list, rules
	end
	local need = {}
	for _, r in ipairs(rules.require) do
		need[r.id] = need[r.id] and { k = "and", v = { need[r.id], r.c } } or r.c
	end
	local list = {}
	for _, item in ipairs(rot.list) do
		if item.id and need[item.id] and not item.cancel then
			local copy = {}
			for k, v in pairs(item) do
				copy[k] = v
			end
			copy.c = item.c and { k = "and", v = { item.c, need[item.id] } } or need[item.id]
			list[#list + 1] = copy
		else
			list[#list + 1] = item
		end
	end
	for _, m in ipairs(rules.move) do
		local from = indexOf(list, m.id)
		if from then
			local item = table.remove(list, from)
			if m.before then
				local at = indexOf(list, m.before)
				table.insert(list, at or (#list + 1), item)
			elseif m.to == "top" then
				table.insert(list, 1, item)
			else
				list[#list + 1] = item
			end
		end
	end
	for _, a in ipairs(rules.add) do
		local item = { id = a.id, c = a.c }
		if need[a.id] then
			item.c = item.c and { k = "and", v = { item.c, need[a.id] } } or need[a.id]
		end
		if a.before then
			table.insert(list, indexOf(list, a.before) or (#list + 1), item)
		elseif a.at == "top" then
			table.insert(list, 1, item)
		else
			list[#list + 1] = item
		end
	end
	tunedCache[rot] = { key = (token or "?") .. ":" .. tostring(spec), list = list }
	return list, rules
end

-- ------------------------------------------------------------------ queue
function Sim.BeginPass()
	pass = { now = GetTime() }
end

-- Spells on the stance bar (seals, presences, stances, forms): the spell ID of
-- each slot, and which one is active. Seals and presences live there rather
-- than on action bars, so "only suggest spells on my bars" lets them through.
local function stanceSlots()
	if pass.stances then
		return pass.stances
	end
	local list = { active = nil, ids = {} }
	local n = num(call(GetNumShapeshiftForms), 0)
	for i = 1, n do
		local _, active, _, sid = call(GetShapeshiftFormInfo, i)
		sid = num(sid, 0)
		if sid > 0 then
			list.ids[sid] = true
			if active then
				list.active = sid
			end
		end
	end
	list.index = num(call(GetShapeshiftForm), 0)
	pass.stances = list
	return list
end
Sim.StanceSlots = stanceSlots

local function onBar(id)
	if ns.db and ns.db.barOnly == false then
		return true
	end
	if stanceSlots().ids[id] then
		return true
	end
	if ns.SpellOnBar then
		return ns.SpellOnBar(id)
	end
	return true
end

local function test(c)
	if c == nil then
		return true
	end
	local ok, res = pcall(ev, c)
	if not ok then
		Sim.lastError = res
		return false
	end
	return truthy(res)
end
Sim.Test = test

-- First three castable spells whose conditions pass, in priority order.
function Sim.BuildQueue(rot)
	rot = rot or Sim.Current()
	if not rot then
		return nil
	end
	Sim.BeginPass()
	local _, token, spec = Sim.Rotations()
	local list, rules = Sim.ListFor(rot, token, spec)
	tuningBlock = {}
	if rules then
		for _, id in ipairs(rules.block) do
			tuningBlock[id] = true
		end
	end
	local q, seen = {}, {}
	for _, item in ipairs(list) do
		if #q >= 3 then
			break
		end
		if item.hold then
			if test(item.c) and #q == 0 then
				break
			end
		elseif item.cancel then
			-- "Cancel" lines (end Metamorphosis): only while its aura is up;
			-- press the same button again. Shown with a CANCEL label.
			local rid = resolve(item.id)
			if rid and not seen[rid] and not Sim.IsBlocked(item.id, rid) and V.auraIsActive({ id = item.id, unit = "player" }) and test(item.c) then
				q[#q + 1] = rid
				seen[rid] = true
				q.cancel = q.cancel or {}
				q.cancel[rid] = true
			end
		elseif item.id then
			local rid = resolve(item.id)
			if rid and not seen[rid] and not Sim.IsBlocked(item.id, rid) and canCast(rid) and onBar(rid) and test(item.c) then
				q[#q + 1] = rid
				seen[rid] = true
			end
		end
	end
	if #q < 3 and not (ns.db and ns.db.simLookahead == false) then
		Sim.FillComingUp(list, q, seen)
	end
	return q
end

-- "Coming up": when fewer than three spells are castable right now, fill the
-- rest with rotation spells that come off cooldown within LOOKAHEAD seconds,
-- soonest first, so the HUD shows what to press next instead of going blank
-- (WoWSims rotations "wait" for a cooldown rather than naming the next spell).
-- They pass the same checks as a normal suggestion apart from the cooldown,
-- and are marked in q.soon so they don't flash until they're ready.
Sim.LOOKAHEAD = 6
function Sim.FillComingUp(list, q, seen)
	local soon = {}
	for _, item in ipairs(list) do
		if item.id and not item.hold then
			local rid = resolve(item.id)
			if rid and not seen[rid] and not Sim.IsBlocked(item.id, rid) and onBar(rid) then
				local cd = cooldownRemain(rid)
				local usable = ns.GAME == "forever" or usableNow(rid) ~= false
				if cd > 0 and cd <= Sim.LOOKAHEAD and usable and test(item.c) then
					soon[#soon + 1] = { rid = rid, cd = cd, order = #soon }
					seen[rid] = true
				end
			end
		end
	end
	table.sort(soon, function(a, b)
		if a.cd ~= b.cd then
			return a.cd < b.cd
		end
		return a.order < b.order
	end)
	for _, s in ipairs(soon) do
		if #q >= 3 then
			break
		end
		q[#q + 1] = s.rid
		q.soon = q.soon or {}
		q.soon[s.rid] = true
	end
end

-- ------------------------------------------------------------------ events
local frame = CreateFrame("Frame")
frame:RegisterEvent("PLAYER_REGEN_DISABLED")
frame:RegisterEvent("PLAYER_REGEN_ENABLED")
frame:SetScript("OnEvent", function(_, event)
	if event == "PLAYER_REGEN_DISABLED" then
		combatStart = GetTime()
	else
		combatStart = 0
	end
end)
